// Connect: channels, inbox, structured WhatsApp ordering.
// Owner: Agent C (see docs/architecture/MODULE_CONTRACTS.md). Other agents
// import from here but do not edit this file.
import { z } from 'zod';
import { idempotencyKey, locale, minor, optionalText, pagination, phoneE164, text, uuid } from './common';
import { CHANNEL_ROUTING_MODES } from './whatsapp-onboarding';

export const connectContractsVersion = 1 as const;

// ---------------------------------------------------------------------------
// Channels
// ---------------------------------------------------------------------------
export const createMessagingChannel = z.discriminatedUnion('transport', [
  z.object({
    transport: z.literal('sandbox'),
    kind: z.literal('whatsapp').default('whatsapp'),
    displayName: text(80),
    branchId: uuid.nullable().optional(),
    orderingEnabled: z.boolean().default(true),
  }).strict(),
  z.object({
    transport: z.literal('meta_cloud'),
    kind: z.literal('whatsapp').default('whatsapp'),
    displayName: text(80),
    displayPhone: z.string().trim().max(30).optional().nullable(),
    phoneNumberId: z.string().regex(/^\d{5,30}$/, 'Meta phone number id (digits)'),
    wabaId: z.string().regex(/^\d{5,30}$/, 'WhatsApp Business Account id (digits)'),
    /** integration_connections row (provider whatsapp_cloud) holding the access token. */
    connectionId: uuid,
    branchId: uuid.nullable().optional(),
    orderingEnabled: z.boolean().default(true),
  }).strict(),
  /**
   * Messenger / Instagram Direct (INT-21 / FT-05): the Page (and linked Instagram account) come from the connection
   * (provider meta_pages), never from this request, and are proven through the Graph API before the channel exists.
   */
  z.object({
    transport: z.literal('meta_page'),
    kind: z.enum(['messenger', 'instagram']),
    displayName: text(80),
    connectionId: uuid,
    branchId: uuid.nullable().optional(),
    orderingEnabled: z.boolean().default(true),
  }).strict(),
]);
export type CreateMessagingChannel = z.infer<typeof createMessagingChannel>;

const metaId = (what: string) => z.string().regex(/^\d{3,30}$/, `${what} (digits)`);

/**
 * WhatsApp Embedded Signup completion (INT-13). The browser received `code` (valid 30 seconds) and the WABA / phone
 * number ids from Meta's popup; the server exchanges the code for the business token, proves ownership, subscribes to
 * webhooks and registers the number. `event` is Meta's session event: the WhatsApp Business app coexistence flow
 * skips registration (the number is already registered).
 */
export const whatsappEmbeddedSignup = z.object({
  code: z.string().trim().min(8).max(2000),
  wabaId: metaId('WhatsApp Business Account id'),
  phoneNumberId: metaId('Phone number id'),
  businessId: metaId('Business portfolio id').optional().nullable(),
  event: z.enum(['FINISH', 'FINISH_WHATSAPP_BUSINESS_APP_ONBOARDING']).default('FINISH'),
  displayName: text(80),
  branchId: uuid.nullable().optional(),
  orderingEnabled: z.boolean().default(true),
}).strict();
export type WhatsAppEmbeddedSignup = z.infer<typeof whatsappEmbeddedSignup>;

export const updateMessagingChannel = z.object({
  displayName: text(80).optional(),
  orderingEnabled: z.boolean().optional(),
  disabled: z.boolean().optional(),
  branchId: uuid.nullable().optional(),
  /** 21-INT: how new conversations on this channel are assigned to staff (WhatsApp stepper step 5). */
  routing: z.enum(CHANNEL_ROUTING_MODES).optional(),
}).strict();

/**
 * 21-INT WhatsApp stepper step 6: "Send a test template to my phone". The channel sends an approved template (on a
 * sandbox channel: the sandbox template) to this number; nothing else is sent to it.
 */
export const whatsappTestTemplate = z.object({
  phone: phoneE164,
  /** Defaults to the connection test template (WHATSAPP_TEST_TEMPLATE) in the restaurant's language. */
  templateName: z.string().regex(/^[a-z0-9_]{1,512}$/).optional(),
  language: locale.optional(),
}).strict();
export type WhatsAppTestTemplate = z.infer<typeof whatsappTestTemplate>;

/** 21-INT step 6 live inbound check: inbound messages on the channel after `since` (ISO time the check started). */
export const whatsappInboundCheckQuery = z.object({ since: z.iso.datetime({ offset: true }).optional() }).strict();

// ---------------------------------------------------------------------------
// Inbox
// ---------------------------------------------------------------------------
export const CONVERSATION_STATUSES = ['bot', 'open', 'handoff', 'closed'] as const;
export type ConversationStatus = (typeof CONVERSATION_STATUSES)[number];

const connectBoolQuery = z.enum(['true', 'false']).transform((v) => v === 'true');
export const inboxConversationFilters = pagination.extend({
  status: z.enum(CONVERSATION_STATUSES).optional(),
  unread: connectBoolQuery.optional(),
  assigned: z.enum(['me', 'unassigned']).optional(),
  channelId: uuid.optional(),
  q: z.string().trim().max(80).optional(),
  /** 21-INBOX: conversations carrying this tag (conversation_tags). */
  tagId: uuid.optional(),
});
export type InboxConversationFilters = z.infer<typeof inboxConversationFilters>;

export const inboxStaffReply = z.object({
  text: z.string().trim().min(1).max(4096).optional(),
  templateName: z.string().regex(/^[a-z0-9_]{1,512}$/).optional(),
  /** Positional values for {{1}}…{{n}} in the template body. */
  variables: z.array(z.string().max(500)).max(10).optional(),
  key: idempotencyKey,
}).strict().refine((v) => !!v.text || !!v.templateName, { message: 'Send text or a template' });
export type InboxStaffReply = z.infer<typeof inboxStaffReply>;

export const inboxHandoffRequest = z.object({ reason: optionalText(300) }).strict();
export const inboxAssignConversation = z.object({ userId: uuid.nullable() }).strict();

/** Staff sandbox simulator: injects an inbound customer message into a SANDBOX channel only. */
export const connectSandboxInbound = z.object({
  channelId: uuid,
  from: phoneE164,
  name: optionalText(80),
  text: z.string().trim().min(1).max(1000).optional(),
  reply: z.object({ id: z.string().min(1).max(256), title: z.string().max(80).optional() }).strict().optional(),
  location: z.object({
    latitude: z.number().min(-90).max(90), longitude: z.number().min(-180).max(180),
    name: optionalText(120), address: optionalText(300),
  }).strict().optional(),
}).strict().refine((v) => [v.text, v.reply, v.location].filter((x) => x !== undefined).length === 1, { message: 'Provide exactly one of text, reply or location' });
export type ConnectSandboxInbound = z.infer<typeof connectSandboxInbound>;

// ---------------------------------------------------------------------------
// Templates (WhatsApp message templates; positional {{1}} … {{n}} placeholders)
// ---------------------------------------------------------------------------
export const messageTemplateInput = z.object({
  name: z.string().regex(/^[a-z0-9_]{1,512}$/, 'lowercase letters, digits and underscores'),
  language: locale.default('en'),
  category: z.enum(['utility', 'marketing', 'authentication']),
  body: z.string().trim().min(1).max(1024),
  /** Human names for {{1}}…{{n}}, in order (e.g. ["order_number", "status"]). */
  variables: z.array(z.string().regex(/^[a-z0-9_]{1,40}$/)).max(10).default([]),
}).strict().superRefine((v, ctx) => {
  const used = [...v.body.matchAll(/\{\{(\d+)\}\}/g)].map((m) => Number(m[1]));
  const max = used.length ? Math.max(...used) : 0;
  for (let i = 1; i <= max; i++) {
    if (!used.includes(i)) ctx.addIssue({ code: 'custom', path: ['body'], message: `Placeholders must be sequential ({{${i}}} missing)` });
  }
  if (max !== v.variables.length) ctx.addIssue({ code: 'custom', path: ['variables'], message: `Name each of the ${max} placeholder(s)` });
});
export type MessageTemplateInput = z.infer<typeof messageTemplateInput>;
export const messageTemplateUpdate = z.object({
  body: z.string().trim().min(1).max(1024).optional(),
  variables: z.array(z.string().regex(/^[a-z0-9_]{1,40}$/)).max(10).optional(),
  category: z.enum(['utility', 'marketing', 'authentication']).optional(),
}).strict();

// ---------------------------------------------------------------------------
// Structured ordering (OFB-style). Free text never creates order lines:
// the customer answers interactive steps and picks products on the hosted page.
// ---------------------------------------------------------------------------
export const ORDERING_STEPS = ['start', 'branch', 'fulfillment', 'customer', 'address', 'menu', 'review', 'payment', 'awaiting_payment', 'completed', 'cancelled', 'expired'] as const;
export type OrderingStep = (typeof ORDERING_STEPS)[number];
export const ORDERING_TERMINAL: readonly OrderingStep[] = ['completed', 'cancelled', 'expired'];

/** Cart lines carry ids and quantities only — never prices (strict: unknown keys are rejected). */
export const orderingCartLine = z.object({
  productId: uuid,
  quantity: z.number().int().min(1).max(99),
  modifiers: z.array(z.object({ groupId: uuid, optionId: uuid }).strict()).max(20).default([]),
  notes: optionalText(200),
}).strict();

export const orderingCartInput = z.object({
  version: z.number().int().min(0),
  lines: z.array(orderingCartLine).min(1).max(60),
}).strict();
export type OrderingCartInput = z.infer<typeof orderingCartInput>;

export const orderingDetailsInput = z.object({
  version: z.number().int().min(0),
  customerName: text(60).optional(),
  address: z.object({
    line1: text(300), area: optionalText(120), city: optionalText(80), notes: optionalText(300),
  }).strict().optional(),
  marketingConsent: z.boolean().optional(),
  /** Messenger / Instagram conversations carry no phone number; delivery orders from them ask for one (INT-21). */
  phone: phoneE164.optional(),
  /** FT-09: the delivery area the guest picked on the hosted page (null clears it); checked against the branch's zones. */
  zoneId: uuid.nullable().optional(),
}).strict();
export type OrderingDetailsInput = z.infer<typeof orderingDetailsInput>;

const utmValue = z.string().trim().max(100).regex(/^[\w.\-~ %+:]*$/).optional();
export const orderAttributionInput = z.object({
  utm_source: utmValue, utm_medium: utmValue, utm_campaign: utmValue, utm_content: utmValue, utm_term: utmValue,
  /** rcid: Resuto campaign id from a tracking link; validated server-side. */
  campaignId: uuid.optional(),
  /** rsid: tracking-link session key, ties the order to the click. */
  sessionKey: z.string().regex(/^[A-Za-z0-9_-]{8,64}$/).optional(),
}).strict();
export type OrderAttributionInput = z.infer<typeof orderAttributionInput>;

export const orderingCheckoutInput = z.object({
  version: z.number().int().min(0),
  paymentMethod: z.enum(['online', 'cod']),
  /** The total the customer reviewed; a different server total returns 409 price_changed. */
  expectedTotalMinor: minor,
  attribution: orderAttributionInput.optional(),
}).strict();
export type OrderingCheckoutInput = z.infer<typeof orderingCheckoutInput>;

export const orderingCancelInput = z.object({ version: z.number().int().min(0) }).strict();
